/* =========================================================
   GLOBAL
   ========================================================= */

html {
  scroll-behavior: smooth;
}

a {
  text-decoration: none;
}

.fj-row {
  display: flex;
  flex-wrap: wrap;
}

.grid-4 {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 20px;
}


/* =========================================================
   CTA
   ========================================================= */

.cta-container {
  padding: 5px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.cta-unit,
button {
  width: 100%;
  margin: 0 auto;
  text-decoration: none !important;
  background-color: rgb(36, 108, 0);
